INSERT INTO public.bpei_assessment_questions(level,ordinal,domain,question,evaluator_answer) VALUES
(1,1,'Matériel','Quelle différence entre RAM et SSD ?','La RAM est temporaire et volatile ; le SSD stocke durablement les données.'),
(1,2,'Matériel','Quel est le rôle du processeur dans un ordinateur ?','Exécuter les instructions et coordonner des traitements informatiques.'),
(1,3,'Démarrage','Que vérifier si un PC n''a aucun voyant ?','Tester alimentation, prise, interrupteur et câble sans ouvrir immédiatement.'),
(1,4,'Démarrage','À quoi sert le BIOS ou UEFI ?','Initialiser les composants puis démarrer le système d''exploitation.'),
(1,5,'Windows','Comment identifier le système installé sur un PC ?','Consulter les informations système et sa version dans les paramètres.'),
(1,6,'Windows','Que faire en premier après un écran bleu ?','Relever le code et le contexte, préserver les données puis investiguer.'),
(1,7,'Windows','Comment examiner l''espace libre d''un disque ?','Utiliser les propriétés du volume ou l''outil de gestion du stockage.'),
(1,8,'Comptes','Quelle différence entre compte local et Microsoft ?','Le compte local est propre au PC ; le compte Microsoft se lie à des services externes.'),
(1,9,'Sécurité','Pourquoi préférer un compte utilisateur non administrateur ?','Limiter les privilèges et donc la portée des erreurs ou logiciels malveillants.'),
(1,10,'Sécurité','Qu''est-ce que l''authentification à deux facteurs ?','L''utilisation de deux catégories de preuves distinctes pour la connexion.'),
(1,11,'Sécurité','Comment réagir à un mail de mot de passe non sollicité ?','Éviter le lien, vérifier depuis le service officiel et signaler la tentative.'),
(1,12,'Confidentialité','Peut-on demander le mot de passe personnel d''un client ?','Éviter cette collecte ; proposer une saisie personnelle ou un accès temporaire autorisé.'),
(1,13,'Réseau','Que fait le DNS dans un réseau ?','Transformer un nom de domaine en adresse IP utilisable.'),
(1,14,'Réseau','À quoi sert une adresse IP locale ?','Identifier un appareil sur un réseau privé pour y échanger des données.'),
(1,15,'Réseau','Quel rôle remplit un routeur domestique ?','Connecter et acheminer le trafic entre le réseau local et Internet.'),
(1,16,'Réseau','Pourquoi un ordinateur n''a pas Internet malgré le Wi-Fi ?','Le Wi-Fi peut être connecté sans route valide, DNS ni accès du fournisseur.'),
(1,17,'Réseau','Que fait un serveur DHCP ?','Distribuer automatiquement les adresses et paramètres IP.'),
(1,18,'Wi-Fi','Pourquoi le signal baisse derrière plusieurs murs ?','Les obstacles atténuent les ondes et peuvent provoquer des interférences.'),
(1,19,'Impression','Quelles vérifications avant de changer une imprimante ?','Contrôler papier, cartouches, messages, connexion, pilote et file d''attente.'),
(1,20,'Stockage','Quelle différence entre sauvegarde et synchronisation ?','Une sauvegarde restaurable protège un état ; une synchronisation peut répliquer les suppressions.'),
(1,21,'Stockage','Quand faut-il faire une sauvegarde avant réparation ?','Avant une opération présentant un risque sur les fichiers, après accord du client.'),
(1,22,'Maintenance','Pourquoi un PC peut-il chauffer anormalement ?','Poussière, ventilation insuffisante, charge ou panne du refroidissement.'),
(1,23,'Diagnostic','Quelle première question poser devant une panne ?','Demander depuis quand elle existe, ce qui a changé et comment la reproduire.'),
(1,24,'Commercial','Pourquoi expliquer et faire accepter le devis ?','Le client doit comprendre prestation, limites, prix total et conditions avant accord.'),
(1,25,'Qualité','Comment vérifier qu''une intervention est terminée ?','Tester le symptôme initial avec le client et documenter le résultat.');